"""Shared core and semantic validation with explicit compatibility scenarios."""

from __future__ import annotations
import re
from pathlib import Path
from typing import Any, Iterable, Mapping, Optional
import yaml
from .limits import LimitsConfig
from .package_snapshot import PackageReadSession
from typing import TYPE_CHECKING
if TYPE_CHECKING:
    from .ontology_catalog import FieldAliasValidationResult, ObjectAliasValidationResult


SUPPORTED_ONTOLOGY_SCHEMA_VERSIONS = frozenset({"0.1", "0.2"})


_FORBIDDEN_RUNTIME_BINDING_KEY_PARTS = frozenset({"endpoint", "token", "secret", "platform"})


def exceeds_limit(count: int, limit: int) -> bool:
    return count > limit


def count_markdown_candidates(paths: Iterable[Path]) -> int:
    # Core includes .md directory candidates; route counts only regular files.
    return sum(1 for path in paths if path.name.lower() != "index.md")


def validate_no_runtime_binding_data(value: Any) -> None:
    """Reject runtime binding data from package-owned declarative contracts."""

    if isinstance(value, Mapping):
        for raw_key, item in value.items():
            key = str(raw_key or "").strip()
            separated = re.sub(r"([a-z0-9])([A-Z])", r"\1_\2", key)
            normalized = re.sub(r"[^a-z0-9]+", "_", separated.lower()).strip("_")
            key_parts = frozenset(part for part in normalized.split("_") if part)
            if normalized == "runtime_binding" or key_parts.intersection(_FORBIDDEN_RUNTIME_BINDING_KEY_PARTS):
                raise ValueError("Forbidden runtime binding field in ontology package: {}".format(key or "<empty>"))
            validate_no_runtime_binding_data(item)
        return
    if isinstance(value, (list, tuple)):
        for item in value:
            validate_no_runtime_binding_data(item)


def validate_ontology_revision(root: Path, *, session: Optional[PackageReadSession] = None) -> dict[str, Any]:
    """Check the core integrity of a complete package revision.

    Safe for read paths: it never runs plugin code.  Plugin-owned contracts
    are admitted separately by :func:`admit_ontology_revision`, only at
    admission points.
    """

    package_root = Path(root)
    session = session or PackageReadSession(package_root)
    if not package_root.is_dir() or package_root.is_symlink():
        raise ValueError("Ontology revision must be a regular directory")
    reject_package_links(package_root)

    manifest_path = package_root / "manifest.yaml"
    if not manifest_path.is_file() or manifest_path.is_symlink():
        raise ValueError("Ontology revision manifest is missing or unsafe")
    try:
        manifest = session.parse_yaml(session.read_text(manifest_path)) or {}
    except (OSError, UnicodeDecodeError, yaml.YAMLError) as exc:
        raise ValueError("Ontology revision manifest cannot be read") from exc
    if not isinstance(manifest, dict):
        raise ValueError("Ontology revision manifest must be a mapping")
    validate_no_runtime_binding_data(manifest)

    schema_version = str(manifest.get("schema_version") or "").strip()
    kind = str(manifest.get("kind") or "").strip()
    if schema_version not in SUPPORTED_ONTOLOGY_SCHEMA_VERSIONS:
        raise ValueError("Unsupported ontology schema version")
    if kind != "ontology-package":
        raise ValueError("Ontology revision must declare kind=ontology-package")
    if schema_version != "0.2":
        return manifest

    operations_dir = package_root / "operations"
    if operations_dir.exists() and not operations_dir.is_dir():
        raise ValueError("Ontology operations path must be a directory")
    if operations_dir.is_dir():
        nested_operations = [path for path in operations_dir.rglob("*.md") if path.parent != operations_dir]
        if nested_operations:
            raise ValueError("Operation Markdown files must use a flat operations directory")

        operation_paths = sorted(operations_dir.glob("*.md"))
        operation_count = count_markdown_candidates(operation_paths)
        limits = LimitsConfig.from_env()
        if exceeds_limit(operation_count, limits.ontology_operation_max_count):
            raise ValueError("Ontology operation count exceeds the configured limit")
        for operation_path in operation_paths:
            try:
                content = session.read_text(operation_path)
            except (OSError, UnicodeDecodeError) as exc:
                raise ValueError("Operation Markdown must be readable UTF-8") from exc
            if exceeds_limit(len(content), limits.operation_max_chars):
                raise ValueError("Operation Markdown exceeds the configured size limit")
            frontmatter = _read_markdown_frontmatter(content, session=session)
            if frontmatter is not None:
                validate_no_runtime_binding_data(frontmatter)

    return manifest


def reject_package_links(root: Path) -> None:
    for path in root.rglob("*"):
        if path.is_symlink() or (hasattr(path, "is_junction") and path.is_junction()):
            raise ValueError("Ontology package contains symbolic links or junctions")


def _read_markdown_frontmatter(
    content: str, *, session: Optional[PackageReadSession] = None
) -> Optional[Mapping[str, Any]]:
    lines = content.splitlines()
    if not lines or lines[0].strip() != "---":
        return None
    try:
        closing = next(index for index in range(1, len(lines)) if lines[index].strip() == "---")
        parsed = (
            session.parse_yaml("\n".join(lines[1:closing])) if session else yaml.safe_load("\n".join(lines[1:closing]))
        ) or {}
    except (StopIteration, yaml.YAMLError):
        return None
    return parsed if isinstance(parsed, Mapping) else None


def validate_md_limits(content: str, folder_key: str) -> Optional[str]:
    if folder_key == "operations":
        max_chars = LimitsConfig.from_env().operation_max_chars
        char_count = len(content)
        if exceeds_limit(char_count, max_chars):
            return "单个逻辑长度超过上限: {} / {} 字符".format(char_count, max_chars)
    if folder_key == "objects":
        max_count = LimitsConfig.from_env().entity_attribute_max_count
        attribute_count = count_first_markdown_table_rows(content)
        if attribute_count > max_count:
            return "单实体属性数量超过上限: {} / {}".format(attribute_count, max_count)
    return None


def count_first_markdown_table_rows(content: str) -> int:
    table_started = False
    rows = []
    for raw_line in content.splitlines():
        line = raw_line.strip()
        if line.startswith("|") and line.endswith("|"):
            table_started = True
            rows.append(line)
            continue
        if table_started and rows:
            break
    if len(rows) < 2:
        return 0
    data_rows = rows[2:]
    return len([row for row in data_rows if row.strip("|").strip()])


def validate_object_attribute_limits(
    objects_dir: Path, *, session: Optional[PackageReadSession] = None
) -> Optional[str]:
    if not objects_dir.exists():
        return None
    max_count = LimitsConfig.from_env().entity_attribute_max_count
    for path in sorted(objects_dir.glob("*.md")):
        try:
            content = session.read_text(path) if session else path.read_text(encoding="utf-8")
        except UnicodeDecodeError:
            return "{} 编码必须是 UTF-8".format(path.name)
        attribute_count = count_first_markdown_table_rows(content)
        if attribute_count > max_count:
            return "{}: 单实体属性数量超过上限: {} / {}".format(
                path.name,
                attribute_count,
                max_count,
            )
    return None


def validate_ontology_tree_limits(root_dir: Path, *, session: Optional[PackageReadSession] = None) -> Optional[str]:
    limits = LimitsConfig.from_env()
    objects_count = count_markdown_files(root_dir / "objects")
    if objects_count > limits.ontology_object_max_count:
        return "单本体实体数量已达上限: {} / {}".format(
            objects_count,
            limits.ontology_object_max_count,
        )
    operations_count = count_markdown_files(root_dir / "operations")
    if exceeds_limit(operations_count, limits.ontology_operation_max_count):
        return "单本体流程数量已达上限: {} / {}".format(
            operations_count,
            limits.ontology_operation_max_count,
        )
    attribute_error = validate_object_attribute_limits(root_dir / "objects", session=session)
    if attribute_error:
        return attribute_error
    operations_dir = root_dir / "operations"
    if not operations_dir.exists():
        return None
    for path in sorted(operations_dir.glob("*.md")):
        try:
            content = session.read_text(path) if session else path.read_text(encoding="utf-8")
        except UnicodeDecodeError:
            return "{} 编码必须是 UTF-8".format(path.name)
        validation_error = validate_md_limits(
            content,
            "operations",
        )
        if validation_error:
            return "{}: {}".format(path.name, validation_error)
    return None


def count_markdown_files(folder_path: Path) -> int:
    if not folder_path.is_dir():
        return 0

    return count_markdown_candidates(
        child for child in folder_path.iterdir() if child.is_file() and child.suffix.lower() == ".md"
    )


def validate_imported_object_aliases(
    root: Path, *, session: Optional[PackageReadSession] = None
) -> ObjectAliasValidationResult:
    """Validate object aliases, mapping readability and value bindings before installation."""
    from .ontology_catalog import (
        ObjectAliasValidationResult,
        load_object_data_mappings,
        validate_object_aliases,
        validate_object_data_mappings,
        validate_value_bindings,
    )

    session = session or PackageReadSession(root)
    validation = validate_object_aliases(Path(root), session=session)
    mappings = load_object_data_mappings(Path(root), session=session)
    mapping_error = validate_object_data_mappings(Path(root), mappings=mappings)
    binding_validation = validate_value_bindings(Path(root), mappings=mappings)
    raw_errors = (
        *validation.errors,
        mapping_error,
        *binding_validation.errors,
    )
    error_set: set[str] = set()
    for error in raw_errors:
        if error:
            error_set.add(error)
    errors = sorted(error_set)
    warnings = sorted(set((*validation.warnings, *binding_validation.warnings)))
    if not errors and not warnings:
        return validation
    return ObjectAliasValidationResult(
        errors=tuple(errors),
        warnings=tuple(warnings),
    )


def validate_imported_field_aliases(
    root: Path, *, session: Optional[PackageReadSession] = None
) -> FieldAliasValidationResult:
    """Validate object field aliases before installation."""
    from .ontology_catalog import validate_field_aliases

    return validate_field_aliases(Path(root), session=session)
